#include <iostream>
using namespace std;

class Titik {
public:
    int x = 0;
    int y = 0;
};

class Garis {
private:
    Titik awal;
    Titik akhir;

public:
    Garis(Titik a, Titik b) : awal(a), akhir(b) {
    }

    int panjangManhattan() const {
        int dx = awal.x - akhir.x;
        int dy = awal.y - akhir.y;
        if (dx < 0) dx = -dx;
        if (dy < 0) dy = -dy;
        return dx + dy;
    }
};

int main() {
    Titik a, b;
    cin >> a.x >> a.y;
    cin >> b.x >> b.y;
    Garis g(a, b);
    cout << g.panjangManhattan() << endl;
    return 0;
}

