#include <iostream>
using namespace std;

class Titik {
public:
    int x = 0;
    int y = 0;
};

class PersegiPanjang {
private:
    Titik kiriBawah;
    Titik kananAtas;

public:
    PersegiPanjang(Titik a, Titik b) : kiriBawah(a), kananAtas(b) {
    }

    int lebar() const {
        return kananAtas.x - kiriBawah.x;
    }

    int tinggi() const {
        return kananAtas.y - kiriBawah.y;
    }

    int luas() const {
        return lebar() * tinggi();
    }

    int keliling() const {
        return 2 * (lebar() + tinggi());
    }
};

int main() {
    Titik a, b;
    cin >> a.x >> a.y;
    cin >> b.x >> b.y;
    PersegiPanjang p(a, b);
    cout << p.luas() << " " << p.keliling() << endl;
    return 0;
}

