#include <iostream>
#include <string>
using namespace std;

class Roda {
private:
    int tekanan;

public:
    Roda(int t) : tekanan(t) {
    }

    bool cukup() const {
        return tekanan >= 30;
    }
};

class Sepeda {
private:
    Roda depan;
    Roda belakang;

public:
    Sepeda(int d, int b) : depan(d), belakang(b) {
    }

    string status() const {
        if (depan.cukup() && belakang.cukup()) {
            return "siap jalan";
        }
        if (!depan.cukup() && !belakang.cukup()) {
            return "pompa kedua roda";
        }
        if (!depan.cukup()) {
            return "pompa roda depan";
        }
        return "pompa roda belakang";
    }
};

int main() {
    int d, b;
    cin >> d >> b;
    Sepeda sepeda(d, b);
    cout << sepeda.status() << endl;
    return 0;
}

