    int harga = 0;
    int jumlah = 0;

public:
    void isi(const string &n, int h, int j) {
        nama = n;
        harga = h;
        jumlah = j;
    }

    string getNama() const {
        return nama;
    }

    int subtotal() const {
        return harga * jumlah;
    }
