private:
    Butir isi[10];
    int banyak = 0;

public:
    void tambah(const string &n, int h, int j) {
        isi[banyak].isi(n, h, j);
        banyak++;
    }

    int total() const {
        auto t = 0;
        for (int k = 0; k < banyak; k++) {
            t += isi[k].subtotal();
        }
        return t;
    }

    void cetak() const {
        for (int k = 0; k < banyak; k++) {
            cout << isi[k].getNama() << ": " << isi[k].subtotal() << endl;
        }
        cout << "Total: " << total() << endl;
