class Prajurit {
private:
    string nama;
    int kesehatan = 0;

public:
    void isi(const string &n, int k) {
        nama = n;
        kesehatan = k;
    }

    void terluka(int besar) {
        kesehatan -= besar;
        if (kesehatan < 0) {
            kesehatan = 0;
        }
    }

    int getKesehatan() const {
        return kesehatan;
    }
};

class Regu {
private:
    Prajurit *anggota[10];
    int banyak = 0;

public:
    void gabung(Prajurit *p) {
        anggota[banyak] = p;
        banyak++;
    }

    int kekuatan() const {
        auto total = 0;
        for (int k = 0; k < banyak; k++) {
            total += anggota[k]->getKesehatan();
        }
        return total;
    }
};

int main() {
    int n, m;
    cin >> n;
    Prajurit barak[10];
    for (int k = 0; k < n; k++) {
        string nama;
        int sehat;
        cin >> nama >> sehat;
        barak[k].isi(nama, sehat);
    }
    cin >> m;
    Regu regu;
    for (int k = 0; k < m; k++) {
        int nomor;
        cin >> nomor;
        regu.gabung(&barak[nomor - 1]);
    }
    int korban, besar;
    cin >> korban >> besar;
    cout << regu.kekuatan() << endl;
    barak[korban - 1].terluka(besar);
    cout << regu.kekuatan() << endl;
    return 0;
}

