#include <iostream>
using namespace std;

class Titik {
public:
    int x = 0;
    int y = 0;
};

class Segitiga {
private:
    Titik sudut[3];

public:
    Segitiga(Titik a, Titik b, Titik c) {
        sudut[0] = a;
        sudut[1] = b;
        sudut[2] = c;
    }

    int luasGanda() const {
        auto hasil = sudut[0].x * (sudut[1].y - sudut[2].y)
                   + sudut[1].x * (sudut[2].y - sudut[0].y)
                   + sudut[2].x * (sudut[0].y - sudut[1].y);
        if (hasil < 0) {
            hasil = -hasil;
        }
        return hasil;
    }
};

int main() {
    Titik a, b, c;
    cin >> a.x >> a.y;
    cin >> b.x >> b.y;
    cin >> c.x >> c.y;
    Segitiga s(a, b, c);
    if (s.luasGanda() == 0) {
        cout << "Ketiga titik segaris" << endl;
    } else {
        cout << "Luas x 2 = " << s.luasGanda() << endl;
    }
    return 0;
}

#include <iostream>
#include <iomanip>
#include <string>
using namespace std;

class MataKuliah {
private:
    string kode;
    int sks = 0;
    char huruf = 'E';

public:
    void isi(const string &k, int s, char h) {
        kode = k;
        sks = s;
        huruf = h;
    }

    int getSks() const {
        return sks;
    }

    int mutu() const {
        switch (huruf) {
            case 'A': return 4 * sks;
            case 'B': return 3 * sks;
            case 'C': return 2 * sks;
            case 'D': return sks;
            default: return 0;
        }
    }
};

class Transkrip {
private:
    MataKuliah mk[10];
    int banyak = 0;

public:
    void tambah(const string &k, int s, char h) {
        mk[banyak].isi(k, s, h);
        banyak++;
    }

    int totalSks() const {
        auto total = 0;
        for (int k = 0; k < banyak; k++) {
            total += mk[k].getSks();
        }
        return total;
    }

    double ipk() const {
        auto mutu = 0;
        for (int k = 0; k < banyak; k++) {
            mutu += mk[k].mutu();
        }
        return (double) mutu / totalSks();
    }
};

int main() {
    int n;
    cin >> n;
    Transkrip t;
    for (int k = 0; k < n; k++) {
        string kode;
        int sks;
        char huruf;
        cin >> kode >> sks >> huruf;
        t.tambah(kode, sks, huruf);
    }
    cout << "SKS: " << t.totalSks() << endl;
    cout << "IPK: " << fixed << setprecision(2) << t.ipk() << endl;
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

class Tamu {
private:
    string nama;

public:
    void setNama(const string &n) {
        nama = n;
    }

    string getNama() const {
        return nama;
    }
};

class Kamar {
private:
    Tamu *penghuni = nullptr;

public:
    bool masuk(Tamu *t) {
        if (penghuni != nullptr) {
            return false;
        }
        penghuni = t;
        return true;
    }

    bool keluar() {
        if (penghuni == nullptr) {
            return false;
        }
        penghuni = nullptr;
        return true;
    }

    string namaPenghuni() const {
        if (penghuni == nullptr) {
            return "-";
        }
        return penghuni->getNama();
    }
};

int main() {
    Kamar kamar[5];
    Tamu tamu[15];
    auto banyakTamu = 0;
    string perintah;
    while (cin >> perintah) {
        if (perintah == "selesai") {
            break;
        }
        int nomor;
        cin >> nomor;
        if (perintah == "masuk") {
            string nama;
            cin >> nama;
            tamu[banyakTamu].setNama(nama);
            if (kamar[nomor - 1].masuk(&tamu[banyakTamu])) {
                cout << "Kamar " << nomor << ": " << nama << endl;
            } else {
                cout << "Kamar " << nomor << " sudah terisi" << endl;
            }
            banyakTamu++;
        } else if (kamar[nomor - 1].keluar()) {
            cout << "Kamar " << nomor << " dikosongkan" << endl;
        } else {
            cout << "Kamar " << nomor << " memang kosong" << endl;
        }
    }
    for (int k = 0; k < 5; k++) {
        cout << k + 1 << ": " << kamar[k].namaPenghuni() << endl;
    }
    return 0;
}

