    int terisi = 0;

public:
    void setKapasitas(int k) {
        kapasitas = k;
    }

    int naik(int orang) {
        auto bisa = kapasitas - terisi;
        if (orang < bisa) {
            bisa = orang;
        }
        terisi += bisa;
        return bisa;
    }

    int getTerisi() const {
        return terisi;
    }

    int getKapasitas() const {
        return kapasitas;
    }
};

