            auto masuk = gerbong[k].naik(orang);
            if (masuk > 0) {
                cout << " gerbong " << k + 1 << " (" << masuk << ")";
                orang -= masuk;
            }
        }
        if (orang > 0) {
            cout << " tertinggal " << orang;
        }
        cout << endl;
    }

    void laporan() const {
        for (int k = 0; k < banyak; k++) {
