#include <iostream>
#include <string>
using namespace std;

class Pasien {
public:
    string nama;
    bool darurat = false;
};

class Dokter {
private:
    string nama;
    Pasien *antre[20];
    int banyak = 0;

public:
    void setNama(const string &n) {
        nama = n;
    }

    string getNama() const {
        return nama;
    }

    int getBanyak() const {
        return banyak;
    }

    int terima(Pasien *p) {
        auto posisi = banyak;
        if (p->darurat) {
            posisi = 0;
            while (posisi < banyak && antre[posisi]->darurat) {
                posisi++;
            }
        }
        for (int k = banyak; k > posisi; k--) {
            antre[k] = antre[k - 1];
        }
        antre[posisi] = p;
        banyak++;
        return posisi + 1;
    }

    Pasien *panggil() {
        if (banyak == 0) {
            return nullptr;
        }
        auto p = antre[0];
        for (int k = 0; k < banyak - 1; k++) {
            antre[k] = antre[k + 1];
        }
        banyak--;
        return p;
    }

    void cetak() const {
        cout << nama << ":";
        if (banyak == 0) {
            cout << " -";
        }
        for (int k = 0; k < banyak; k++) {
            cout << " " << antre[k]->nama;
        }
        cout << endl;
    }
};

class Klinik {
private:
    Dokter dokter[3];
    Pasien pasien[20];
    int banyakDokter = 0;
    int banyakPasien = 0;

public:
    void tambahDokter(const string &nama) {
        dokter[banyakDokter].setNama(nama);
        banyakDokter++;
    }

    void datang(const string &nama, bool darurat) {
        auto p = &pasien[banyakPasien];
        banyakPasien++;
        p->nama = nama;
        p->darurat = darurat;
        auto pilih = 0;
        for (int k = 1; k < banyakDokter; k++) {
            if (dokter[k].getBanyak() < dokter[pilih].getBanyak()) {
                pilih = k;
            }
        }
        auto urutan = dokter[pilih].terima(p);
        cout << nama << " -> Dokter " << dokter[pilih].getNama() << " (urutan " << urutan << ")" << endl;
    }

    void panggil(const string &nama) {
        for (int k = 0; k < banyakDokter; k++) {
            if (dokter[k].getNama() == nama) {
                auto p = dokter[k].panggil();
                if (p == nullptr) {
                    cout << "Dokter " << nama << " tidak punya pasien" << endl;
                } else {
                    cout << "Dokter " << nama << " memeriksa " << p->nama << endl;
                }
            }
        }
    }

    void laporan() const {
        for (int k = 0; k < banyakDokter; k++) {
            dokter[k].cetak();
        }
    }
};

int main() {
    Klinik klinik;
    int d;
    cin >> d;
    for (int k = 0; k < d; k++) {
        string nama;
        cin >> nama;
        klinik.tambahDokter(nama);
    }
    string perintah;
    while (cin >> perintah) {
        if (perintah == "selesai") {
            break;
        }
        string nama;
        cin >> nama;
        if (perintah == "datang") {
            string jenis;
            cin >> jenis;
            klinik.datang(nama, jenis == "darurat");
        } else {
            klinik.panggil(nama);
        }
    }
    klinik.laporan();
    return 0;
}
